 /** Does an action pattern such as "doc:*" match an action such as "doc:read"? See README.md. */
 export function matchAction(pattern: string, action: string): boolean {
-  throw new Error("not implemented");
+  if (pattern === "*") return true;
+  if (pattern.endsWith(":*")) {
+    const prefix = pattern.slice(0, -1); // keeps the trailing ":"
+    return action.length > prefix.length && action.startsWith(prefix);
+  }
+  return pattern === action;
 }

 /** Does a resource pattern with * and ** segments match a path? See README.md. */
 export function matchResource(pattern: string, resource: string): boolean {
-  throw new Error("not implemented");
+  return matchSegments(splitPath(pattern), splitPath(resource), 0, 0);
 }
+
+function splitPath(path: string): string[] {
+  return path.split("/").filter((segment) => segment !== "");
+}
+
+function matchSegments(pattern: string[], path: string[], pi: number, si: number): boolean {
+  if (pi === pattern.length) return si === path.length;
+
+  const segment = pattern[pi];
+  if (segment === "**") {
+    // Let ** absorb zero or more path segments.
+    for (let k = si; k <= path.length; k++) {
+      if (matchSegments(pattern, path, pi + 1, k)) return true;
+    }
+    return false;
+  }
+
+  if (si === path.length) return false;
+  if (segment !== "*" && segment !== path[si]) return false;
+  return matchSegments(pattern, path, pi + 1, si + 1);
+}
